class Tuple {
  var key: int
  var value: seq<int>

  constructor (k: int, v: seq<int>)
    ensures this.key == k
    ensures this.value == v
  {
    this.key := k;
    this.value := v;
  }
}

class SetPlus {
  ghost var Repr: set<object>
  var store: array<int>
  var nelems: int

  ghost predicate RepInv()
    reads this, Repr, store, nelems
    requires this in Repr
    requires store in Repr
    requires 0 < store.Length
    requires 0 <= nelems <= store.Length
  {
    this in Repr && store in Repr &&
    0 < store.Length &&
    0 <= nelems <= store.Length &&
    // First nelems elements are unique.
    (forall i, j :: 0 <= i < j < nelems ==> store[i] != store[j]) &&
    // elems is exactly the set of the first nelems elements.
    (forall y :: y in elems <==> y in store[..nelems])
  }

  ghost var elems: set<int>

  constructor (size: int)
    requires size > 0
    modifies this
    ensures Repr == {this, store}
    ensures store.Length == size
    ensures nelems == 0
    ensures elems == {}
    ensures RepInv()
  {
    this.store := new int[size];
    this.Repr := {this, store};
    this.nelems := 0;
    this.elems := {};
  }

  method Init(size: int)
    requires size > 0
    modifies this
    ensures Repr == {this, store}
    ensures store.Length == size
    ensures nelems == 0
    ensures elems == {}
    ensures RepInv()
  {
    this.store := new int[size];
    this.Repr := {this, store};
    this.nelems := 0;
    this.elems := {};
  }

  method Insert(x: int)
    requires this in Repr
    requires store in Repr
    requires 0 < store.Length
    requires 0 <= nelems <= store.Length
    requires RepInv()
    requires x !in elems
    modifies this, Repr, store, nelems, elems
    ensures RepInv()
    ensures elems == old(elems) + {x}
  {
    ghost var oldPrefix := store[..nelems];

    if nelems == store.Length {
      var newStore := new int[store.Length + 1];
      var i := 0;
      while i < nelems
        invariant 0 <= i <= nelems
        invariant nelems == store.Length
        invariant newStore.Length == store.Length + 1
        invariant newStore[..i] == store[..i]
      {
        newStore[i] := store[i];
        i := i + 1;
      }

      assert newStore[..nelems] == store[..nelems];
      assert x !in oldPrefix;
      assert forall k :: 0 <= k < nelems ==> store[k] != x;

      newStore[nelems] := x;

      assert newStore[..nelems+1] == oldPrefix + [x];
      assert forall y :: y in elems + {x} <==> y in newStore[..nelems+1];
      assert forall i, j :: 0 <= i < j < nelems+1 ==> newStore[i] != newStore[j];

      Repr := Repr + {newStore};
      store := newStore;
      nelems := nelems + 1;
      elems := elems + {x};
    } else {
      assert nelems < store.Length;
      assert x !in oldPrefix;
      assert forall k :: 0 <= k < nelems ==> store[k] != x;

      store[nelems] := x;

      assert store[..nelems+1] == oldPrefix + [x];
      assert forall y :: y in elems + {x} <==> y in store[..nelems+1];
      assert forall i, j :: 0 <= i < j < nelems+1 ==> store[i] != store[j];

      nelems := nelems + 1;
      elems := elems + {x};
    }
  }

  method Find(x: int) returns (found: bool)
    requires this in Repr
    requires store in Repr
    requires 0 < store.Length
    requires 0 <= nelems <= store.Length
    requires RepInv()
    ensures found <==> x in elems
  {
