    {
      if store[i] == x {
        found := true;
      }
      i := i + 1;
    }

    assert found == (exists k :: 0 <= k < nelems && store[k] == x);
    assert (x in store[..nelems]) == (exists k :: 0 <= k < nelems && store[k] == x);
    assert (x in elems) == (x in store[..nelems]);
  }
}
EOF
