    ghost var oldPrefix := store[..nelems];

    if nelems == store.Length {
      var newStore := new int[store.Length + 1];
      var i := 0;
      while i < nelems
        invariant 0 <= i <= nelems
        invariant nelems == store.Length
        invariant newStore.Length == store.Length + 1
        invariant newStore[..i] == store[..i]
      {
        newStore[i] := store[i];
        i := i + 1;
      }

      assert newStore[..nelems] == store[..nelems];
      assert x !in oldPrefix;
      assert forall k :: 0 <= k < nelems ==> store[k] != x;

      newStore[nelems] := x;

      assert newStore[..nelems+1] == oldPrefix + [x];
      assert forall y :: y in elems + {x} <==> y in newStore[..nelems+1];
      assert forall i, j :: 0 <= i < j < nelems+1 ==> newStore[i] != newStore[j];

      Repr := Repr + {newStore};
      store := newStore;
      nelems := nelems + 1;
      elems := elems + {x};
    } else {
      assert nelems < store.Length;
      assert x !in oldPrefix;
      assert forall k :: 0 <= k < nelems ==> store[k] != x;

      store[nelems] := x;

      assert store[..nelems+1] == oldPrefix + [x];
      assert forall y :: y in elems + {x} <==> y in store[..nelems+1];
      assert forall i, j :: 0 <= i < j < nelems+1 ==> store[i] != store[j];

      nelems := nelems + 1;
      elems := elems + {x};
    }
  }

  method Find(x: int) returns (found: bool)
    requires this in Repr
    requires store in Repr
    requires 0 < store.Length
